cs=ov_read_bytesC45stdpp9bitvector;definitions:bv_extractC56Stdlib6ZArith6BinInt1Z3lebC56Stdlib6ZArith6BinInt1Z6leb_leC47Corelib4Init5Logic5proj1C59OSSVerify5KrLib4LibA5ExecF=evtF_step_accC1?~~~~~~~~~~~~~~~c59OSSVerify5KrLib5AsanW9AF_atexit<APNEED_LOCKSC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib4LibA6Shadow5KHIGHC1?~~~~~~~~~~~~~~~K46Stdlib9micromega=RingMicromega3Op201K4ELinuxProcessSemantics5Riscv5Instr5aluop01I4ELinuxProcessSemantics?LinuxProcessSem>RiscvSemantics=machine_state00K47Corelib4Init9Datatypes4bool02I4ELinuxProcessSemantics5Riscv5Instr5instr00C4ELinuxProcessSemantics?LinuxProcessSem>RiscvSemantics=memory_accessK4ELinuxProcessSemantics5Riscv5Instr5msize04I4ELinuxProcessSemantics5Riscv3Sem4core00K47Corelib4Init5Logic4True01I47Corelib4Init5Logic5False00K47Corelib7Numbers7BinNums1N01C4ELinuxProcessSemantics5Riscv3Sem2w0C59OSSVerify5KrLib3Lib6MState6w0_litC1?~~~~~~~~~~~~~~~C4ELinuxProcessSemantics5Riscv3Sem2w1C59OSSVerify5KrLib3Lib6MState6w1_litC1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib4LibA5ExecF9footprintC1?~~~~~~~~~~~~~~~c59OSSVerify5KrLib5AsanW9AF_atexit8APATEXITC1?~~~~~~~~~~~~~~~K46Stdlib9micromega:ZMicromega;ZArithProof01K4ELinuxProcessSemantics5Riscv5Instr5msize01K4ELinuxProcessSemantics5Riscv5Instr;branch_cond01K4ELinuxProcessSemantics5Riscv5Instr;branch_cond02K4ELinuxProcessSemantics5Riscv5Instr5msize03K4ELinuxProcessSemantics5Riscv5Instr5aluop03K4ELinuxProcessSemantics5Riscv5Instr;branch_cond03".
Import ListNotations.
Open Scope Z_scope.

Import ITree.Exc.
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.

Notation mem := (word -> option byte).

(* [comment removed for export] *)
Ltac sort_lits :=
  repeat (match goal with H : rw_cells asegs _ (Zpos ?p) _ |- _ =>
            tryif (match goal with H' : rw_cells asegs _ (Zpos ?p') _ |- _ =>
                     lazymatch eval vm_compute in (Z.ltb (Zpos p') (Zpos p)) with true => idtac | false => fail end end)
            then fail
            else (move H at bottom; lazymatch type of H with ?T => change T with (sf_hide T) in H end)
          end); sf_unhide.
Ltac hstep := sort_lits; zstep; fix_lit_store.
(* [comment removed for export] *)
Ltac hyp_by_addr :=
  lazymatch goal with
  | |- rw_cells _ _ ?A _ => match goal with H : rw_cells _ _ A _ |- _ => exact H end
  | |- bytes_at _ _ ?A _ => match goal with H : bytes_at _ _ A _ |- _ => exact H end
  | |- stk _ _ _ _ => match goal with H : stk _ _ _ _ |- _ => exact H end
  | |- mem_inv _ _ => match goal with H : mem_inv _ _ |- _ => exact H end
  end.
Ltac astep := hstep; try (first [if_true | if_false]).
Ltac at_pc p := lazymatch goal with |- evtF _ _ _ (MS _ _ (Z_to_bv 64 ?q) _ _ _ _) => constr_eq q p end.
Ltac steps_to p := repeat (tryif at_pc p then fail else astep).

(* [comment removed for export] *)
(* [comment removed for export] *)
(* [comment removed for export] *)
Definition APATEXIT : Z := 0x9f12c.       (* [comment removed for export] *)
Definition APATX : Z := 0x60a960.         (* [comment removed for export] *)
Definition APATX_CALLFN : Z := 0x9f1f0.   (* [comment removed for export] *)
Definition APNEED_LOCKS : Z := 0x60aba3.  (* [comment removed for export] *)
Definition ACOV_HOOK : Z := 0x6f588.      (* [comment removed for export] *)
Definition ACOV_FLAG : Z := 0x149820.     (* [comment removed for export] *)
(* [comment removed for export] *)
Definition APEXIT_GUARD : Z := 0x7ff50.   (* [comment removed for export] *)
Definition APAEF_INCB : Z := 0x5e9fd4.    (* [comment removed for export] *)

(* [comment removed for export] *)
Definition atx_cellsA (slot f1 a1 : Z) (m : mem) : Prop :=
  rw_cells asegs m 0x60a960 [C1 (Z_to_bv 8 0)]
  /\ rw_cells asegs m 0x60a964 [C4 (Z_to_bv 64 0)]
  /\ rw_cells asegs m 0x60a968 [C4 (Z_to_bv 64 slot)]
  /\ rw_cells asegs m 0x60a970 [C8 (Z_to_bv 64 0x60a978)]
  /\ rw_cells asegs m 0x60a978 [C8 (Z_to_bv 64 0)]
  /\ rw_cells asegs m 0x60a980 [C8 (Z_to_bv 64 APATX_CALLFN)]
  /\ rw_cells asegs m 0x60aa80 [C8 (Z_to_bv 64 ACOV_HOOK)]
  /\ rw_cells asegs m 0x60a988 [C8 (Z_to_bv 64 f1)]
  /\ rw_cells asegs m 0x60aa88 [C8 (Z_to_bv 64 a1)].

(* [comment removed for export] *)
Definition atx_stateA (reg : bool) (m : mem) : Prop :=
  atx_cellsA (if reg then 2 else 1) (if reg then APATX_CALLFN else 0) (if reg then APEXIT_GUARD else 0) m
  /\ rw_cells asegs m APAEF_INCB [C1 (Z_to_bv 8 0)]
  /\ rw_cells asegs m ACOV_FLAG [C1 (Z_to_bv 8 0)].

Definition atx_addrA (a : Z) : Prop :=
  (0x60a960 <= a < 0x60a961)%Z \/ (0x60a964 <= a < 0x60a96c)%Z \/ (0x60a970 <= a < 0x60a990)%Z \/ (0x60aa80 <= a < 0x60aa90)%Z.
Definition atx_state_addrA (a : Z) : Prop := atx_addrA a \/ (0x5e9fd4 <= a < 0x5e9fd5)%Z \/ (0x149820 <= a < 0x149821)%Z.

Lemma atx_cellsA_agree : forall (P : Z -> Prop) m m' slot f1 a1,
  magree asegs P m m' -> (forall a, atx_addrA a -> P a) -> atx_cellsA slot f1 a1 m -> atx_cellsA slot f1 a1 m'.
Proof.
